UPDATE ast_product_type_source_mapping
SET mapping_status = 'CONFLICT',
    conflict_product_type_code = #{update.productTypeCode},
    conflict_source_version = #{update.sourceVersion},
    conflict_source_updated_at = #{update.sourceUpdatedAt},
    conflict_payload_hash = #{update.payloadHash}
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.mappingId}
  AND deleted = b'0'
